-- ═══════════════════════════════════════════════════════════════════════════
--  0163 — Khalidiyah's indicator views, the rest (0162's header), the second
--         figures, the status and public views, and v_indicator_actual
--
--  GENERATED by supabase/khalidiyah/gen_views.py.
-- ═══════════════════════════════════════════════════════════════════════════

create temp table _0163_actual_before on commit drop as
  select * from public.v_indicator_actual
   where municipality_id in ('00000000-0000-4000-8000-00000000005a', '00000000-0000-4000-8000-0000000000a1');

-- ── SO3-0 ·
--    formula: "[ COUNT(F070 WHERE COUNT DISTINCT(F147) ≥ 2) ÷ COUNT
--      DISTINCT(FORM-12.F058) ] × 100"
--    frequency: "Annual / end of period"
create view public.v_ind_khld_so3_0 as
select rp.code as period_code,
       case when rp.start_date > current_date or count(v.id) = 0 then null::numeric
            else round(100.0 * count(*) filter (
                   where (select count(distinct o.occasion_id) from public.v_khld_volunteer_occasion o
                           where o.volunteer_id = v.id and o.report_date <= rp.end_date) >= 2) / count(v.id), 1) end as actual,
       case when rp.start_date > current_date then null::numeric else count(v.id)::numeric end as denominator,
       m.id as municipality_id
  from public.municipality m
  join public.reporting_period rp on rp.municipality_id = m.id
  left join (public.khld_volunteer v join public.person p on p.id = v.person_id and p.deleted_at is null)
    on v.municipality_id = m.id and v.deleted_at is null and v.application_status = 'approved'
   and (v.created_at at time zone 'Asia/Amman')::date <= rp.end_date
 where m.code = 'KHLD'
 group by m.id, rp.code, rp.start_date;

-- ── E1 ·
--    formula: "Established = 1 IF COUNT(FORM-11 WHERE F142 = "Yes" AND F052
--      uploaded) ≥ 1 (or FORM-22 F189 = SO3-E1 AND F194 = "Established");
--      else 0"
--    frequency: "By Dec 2026"
create view public.v_ind_khld_e1 as
select rp.code as period_code,
       case when rp.start_date > current_date then null when e.established_on <= rp.end_date then 1 else 0 end::numeric as actual,
       null::numeric as denominator, m.id as municipality_id
  from public.municipality m
  join public.reporting_period rp on rp.municipality_id = m.id
  left join public.v_khld_milestone_established e on e.municipality_id = m.id and e.milestone = 'so3_e1'
 where m.code = 'KHLD';

-- ── F1 ·
--    formula: "Established = 1 IF F194 = "Established" AND F193 contains all
--      4 components; else 0"
--    frequency: "Launch by Apr 2027"
create view public.v_ind_khld_f1 as
select rp.code as period_code,
       case when rp.start_date > current_date then null when e.established_on <= rp.end_date then 1 else 0 end::numeric as actual,
       null::numeric as denominator, m.id as municipality_id
  from public.municipality m
  join public.reporting_period rp on rp.municipality_id = m.id
  left join public.v_khld_milestone_established e on e.municipality_id = m.id and e.milestone = 'so3_f1'
 where m.code = 'KHLD';

-- ── F2 ·
--    formula: "COUNT DISTINCT(FORM-12.F058 WHERE EXISTS FORM-13.F070 = F058)"
--    frequency: "Cumulative from Apr 2027"
create view public.v_ind_khld_f2 as
select rp.code as period_code, case when rp.start_date > current_date then null else count(f.volunteer_id) end::numeric as actual, null::numeric as denominator, m.id as municipality_id
  from public.municipality m
  join public.reporting_period rp on rp.municipality_id = m.id
  left join (select o.municipality_id, o.volunteer_id, min(o.report_date) as first_on
               from public.v_khld_volunteer_occasion o group by o.municipality_id, o.volunteer_id) f
    on f.municipality_id = m.id and f.first_on <= rp.end_date
 where m.code = 'KHLD'
 group by m.id, rp.code, rp.start_date;

-- ── F3 ·
--    formula: "SUM(FORM-07.F127 WHERE F126 = "Held")"
--    frequency: "Cumulative"
create view public.v_ind_khld_f3 as
select rp.code as period_code, case when rp.start_date > current_date then null else coalesce(sum(x.action_days), 0) end::numeric as actual, null::numeric as denominator, m.id as municipality_id
  from public.municipality m
  join public.reporting_period rp on rp.municipality_id = m.id
  left join (public.khld_campaign x join public.ref_khld_event_status s on s.id = x.status_id and s.code = 'held')
    on x.municipality_id = m.id and x.deleted_at is null and x.start_date <= rp.end_date
 where m.code = 'KHLD'
 group by m.id, rp.code, rp.start_date;

-- ── SO4-0 ·
--    formula: "[ COUNT DISTINCT(F206 WHERE F208 = "Yes") ÷ COUNT
--      DISTINCT(F206) ] × 100"
--    frequency: "Annual"
create view public.v_ind_khld_so4_0 as
select rp.code as period_code,
       case when count(l.person_id) = 0 then null::numeric
            else round(100.0 * count(*) filter (where l.increased_opportunities) / count(l.person_id), 1) end as actual,
       count(l.person_id)::numeric as denominator,
       m.id as municipality_id
  from public.municipality m
  join public.reporting_period rp on rp.municipality_id = m.id
  left join lateral (
    select distinct on (s.person_id) s.person_id, s.increased_opportunities
      from public.khld_producer_survey s
      join public.person p on p.id = s.person_id and p.deleted_at is null
     where s.municipality_id = m.id and s.deleted_at is null
       and s.survey_date between date_trunc('year', rp.end_date)::date and rp.end_date
       and rp.start_date <= current_date
     order by s.person_id, s.survey_date desc, s.created_at desc
  ) l on true
 where m.code = 'KHLD'
 group by m.id, rp.code;

-- ── G1 ·
--    formula: "COUNT DISTINCT(F197 WHERE COUNT DISTINCT(F200 core & attended)
--      = COUNT(FORM-14 WHERE F150 = "Yes" in that cycle))"
--    frequency: "Cumulative 2027–2028"
create view public.v_ind_khld_g1 as
select rp.code as period_code, case when rp.start_date > current_date then null else count(c.person_id) end::numeric as actual, null::numeric as denominator, m.id as municipality_id
  from public.municipality m
  join public.reporting_period rp on rp.municipality_id = m.id
  left join public.v_khld_guidance_completed c
    on c.municipality_id = m.id and c.completed_on <= rp.end_date
 where m.code = 'KHLD'
 group by m.id, rp.code, rp.start_date;

-- ── G2 ·
--    formula: "COUNT DISTINCT(FORM-23.F197 WHERE F199 ≠ "Guidance session" OR
--      F201 = "Attended")"
--    frequency: "Cumulative from 2027"
create view public.v_ind_khld_g2 as
select rp.code as period_code, case when rp.start_date > current_date then null else count(f.person_id) end::numeric as actual, null::numeric as denominator, m.id as municipality_id
  from public.municipality m
  join public.reporting_period rp on rp.municipality_id = m.id
  left join (
    select s.municipality_id, s.person_id, min(s.support_date) as first_on
      from public.khld_enterprise_support s
      join public.ref_khld_support_type st on st.id = s.support_type_id
      join public.person p on p.id = s.person_id and p.deleted_at is null
     where s.deleted_at is null and (st.code <> 'guidance' or s.attended)
     group by s.municipality_id, s.person_id
  ) f on f.municipality_id = m.id and f.first_on <= rp.end_date
 where m.code = 'KHLD'
 group by m.id, rp.code, rp.start_date;

-- ── H1 ·
--    formula: "Market days = SUM(FORM-16.F094 WHERE F154 = "Held"); Number of
--      markets = COUNT(FORM-16 WHERE F154 = "Held")"
--    frequency: "Cumulative from Apr 2027"
create view public.v_ind_khld_h1 as
select rp.code as period_code, case when rp.start_date > current_date then null else coalesce(sum(x.actual_days), 0) end::numeric as actual, null::numeric as denominator, m.id as municipality_id
  from public.municipality m
  join public.reporting_period rp on rp.municipality_id = m.id
  left join (public.khld_market x join public.ref_khld_event_status s on s.id = x.status_id and s.code = 'held')
    on x.municipality_id = m.id and x.deleted_at is null and x.start_date <= rp.end_date
 where m.code = 'KHLD'
 group by m.id, rp.code, rp.start_date;

-- ── H2 ·
--    formula: "Participations = COUNT(FORM-18); Per market = COUNT(FORM-18
--      GROUP BY F157); Unique vendors = COUNT DISTINCT(FORM-18.F112)"
--    frequency: "Every market day; cumulative"
create view public.v_ind_khld_h2 as
select rp.code as period_code, case when rp.start_date > current_date then null else count(x.id) end::numeric as actual, null::numeric as denominator, m.id as municipality_id
  from public.municipality m
  join public.reporting_period rp on rp.municipality_id = m.id
  left join (public.khld_market_attendance x
             join public.khld_market k on k.id = x.market_id and k.deleted_at is null
             join public.ref_khld_event_status s on s.id = k.status_id and s.code = 'held'
             join public.person p on p.id = x.person_id and p.deleted_at is null)
    on x.municipality_id = m.id and x.deleted_at is null and x.report_date <= rp.end_date
 where m.code = 'KHLD'
 group by m.id, rp.code, rp.start_date;

-- ── the second figures ────────────────────────────────────────────────────
-- A3: the number of contributions; H1: the number of markets held; H2:
-- unique vendors (F112) with an attendance at a market held, on the first.
create or replace view public.v_khld_indicator_unique as
select x.code, rp.code as period_code,
       case x.code
         when 'A3' then (select count(*) from public.khld_contribution c
                          where c.municipality_id = m.id and c.deleted_at is null
                            and c.date_received between date_trunc('year', rp.end_date)::date and rp.end_date)
         when 'H1' then (select count(*) from public.khld_market k
                           join public.ref_khld_event_status s on s.id = k.status_id and s.code = 'held'
                          where k.municipality_id = m.id and k.deleted_at is null
                            and k.start_date <= rp.end_date)
         when 'H2' then (select count(*) from (
                           select a.person_id, min(a.report_date) as first_on
                             from public.khld_market_attendance a
                             join public.khld_market k on k.id = a.market_id and k.deleted_at is null
                             join public.ref_khld_event_status s on s.id = k.status_id and s.code = 'held'
                             join public.person p on p.id = a.person_id and p.deleted_at is null
                            where a.municipality_id = m.id and a.deleted_at is null
                            group by a.person_id) f
                          where f.first_on <= rp.end_date)
       end::numeric as unique_actual,
       m.id as municipality_id
  from public.municipality m
  join public.reporting_period rp on rp.municipality_id = m.id and rp.start_date <= current_date
  cross join (values ('A3'), ('H1'), ('H2')) x(code)
 where m.code = 'KHLD'
   and (auth.uid() is null or public.is_staff() or public."current_role"() = 'partner_viewer')
   and (auth.uid() is null or public.can_see_municipality(m.id));

-- ── what cannot compute: nothing, and the columns stay for the dashboard ──
create or replace view public.v_khld_indicator_status as
select i.municipality_id, i.code, i.full_code, null::text as reason, null::text as detail, null::text as milestone_code
  from public.indicator i
  join public.municipality m on m.id = i.municipality_id and m.code = 'KHLD'
 where (auth.uid() is null or public.is_staff() or public."current_role"() = 'partner_viewer')
   and (auth.uid() is null or public.can_see_municipality(i.municipality_id));

-- ── the public page: published activities (FORM-08) and markets (FORM-16)
--    that have not ended; titles, dates, types and descriptions only.
--    A definer view over base tables, the four filters in the view itself
--    (0120, 0152). The forms have no time or place fields.
create or replace view public.v_public_khld_whats_on
with (security_invoker = false) as
select a.id,
       'activity'::text as kind,
       a.activity_name as title,
       a.start_date as on_date,
       null::text as time_from,
       null::text as time_to,
       null::text as place_en,
       null::text as place_ar,
       t.label_en as type_en,
       t.label_ar as type_ar,
       a.description,
       m.slug as municipality_slug
  from public.khld_activity a
  join public.municipality m on m.id = a.municipality_id and m.is_active and m.deleted_at is null
  left join public.ref_khld_activity_type t on t.id = a.activity_type_id
 where a.is_published and a.deleted_at is null and a.end_date >= current_date
union all
select k.id,
       'market'::text,
       k.name,
       k.start_date,
       null::text,
       null::text,
       null::text,
       null::text,
       o.label_en,
       o.label_ar,
       k.description,
       m.slug
  from public.khld_market k
  join public.municipality m on m.id = k.municipality_id and m.is_active and m.deleted_at is null
  left join public.ref_khld_market_occasion o on o.id = k.occasion_id
 where k.is_published and k.deleted_at is null and k.end_date >= current_date;

-- ── v_indicator_actual: 0153's definition plus the 21 branches ────────────
create or replace view public.v_indicator_actual as
select code, period_code, actual, denominator, municipality_id
  from (
    select 'IMP-0'::text as code, period_code, actual, denominator, municipality_id from public.v_ind_imp_0
    union all select 'A1',   period_code, actual, denominator, municipality_id from public.v_ind_a1
    union all select 'A1.2', period_code, actual, denominator, municipality_id from public.v_ind_a1_2
    union all select 'A1.3', period_code, actual, denominator, municipality_id from public.v_ind_a1_3
    union all select 'B1',   period_code, actual, denominator, municipality_id from public.v_ind_b1
    union all select 'B1.1', period_code, actual, denominator, municipality_id from public.v_ind_b1_1
    union all select 'B1.2', period_code, actual, denominator, municipality_id from public.v_ind_b1_2
    union all select 'C1',   period_code, actual, denominator, municipality_id from public.v_ind_c1
    union all select 'C1.1', period_code, actual, denominator, municipality_id from public.v_ind_c1_1
    union all select 'C1.2', period_code, actual, denominator, municipality_id from public.v_ind_c1_2
    union all select 'C1.3', period_code, actual, denominator, municipality_id from public.v_ind_c1_3
    union all select 'D0.1', period_code, actual, denominator, municipality_id from public.v_ind_d0_1
    union all select 'D0.2', period_code, actual, denominator, municipality_id from public.v_ind_d0_2
    union all select 'E0.1', period_code, actual, denominator, municipality_id from public.v_ind_e0_1
    union all select 'E0.2', period_code, actual, denominator, municipality_id from public.v_ind_e0_2
    union all select 'F0.1', period_code, actual, denominator, municipality_id from public.v_ind_f0_1
    union all select 'G0.1', period_code, actual, denominator, municipality_id from public.v_ind_g0_1
    union all select 'G0.2', period_code, actual, denominator, municipality_id from public.v_ind_g0_2
    union all select 'G0.3', period_code, actual, denominator, municipality_id from public.v_ind_g0_3
    union all select 'G0.4', period_code, actual, denominator, municipality_id from public.v_ind_g0_4
    -- Ramtha (0132)
    union all select 'IMP-0', period_code, actual, denominator, municipality_id from public.v_ind_rmth_imp_0
    union all select 'SO1-0', period_code, actual, denominator, municipality_id from public.v_ind_rmth_so1_0
    union all select 'A1.2',  period_code, actual, denominator, municipality_id from public.v_ind_rmth_a1_2
    union all select 'A1.3',  period_code, actual, denominator, municipality_id from public.v_ind_rmth_a1_3
    union all select 'B1',    period_code, actual, denominator, municipality_id from public.v_ind_rmth_b1
    union all select 'B1.1',  period_code, actual, denominator, municipality_id from public.v_ind_rmth_b1_1
    union all select 'B1.2',  period_code, actual, denominator, municipality_id from public.v_ind_rmth_b1_2
    union all select 'SO2-0', period_code, actual, denominator, municipality_id from public.v_ind_rmth_so2_0
    union all select 'C1',    period_code, actual, denominator, municipality_id from public.v_ind_rmth_c1
    union all select 'C1.1',  period_code, actual, denominator, municipality_id from public.v_ind_rmth_c1_1
    union all select 'C1.2',  period_code, actual, denominator, municipality_id from public.v_ind_rmth_c1_2
    union all select 'SO3-0', period_code, actual, denominator, municipality_id from public.v_ind_rmth_so3_0
    union all select 'E0.1',  period_code, actual, denominator, municipality_id from public.v_ind_rmth_e0_1
    union all select 'E0.2',  period_code, actual, denominator, municipality_id from public.v_ind_rmth_e0_2
    union all select 'E0.3',  period_code, actual, denominator, municipality_id from public.v_ind_rmth_e0_3
    union all select 'F0.1',  period_code, actual, denominator, municipality_id from public.v_ind_rmth_f0_1
    union all select 'F0.2',  period_code, actual, denominator, municipality_id from public.v_ind_rmth_f0_2
    -- Khalidiyah (0162, 0163)
    union all select 'IMP-0', period_code, actual, denominator, municipality_id from public.v_ind_khld_imp_0
    union all select 'SO1-0', period_code, actual, denominator, municipality_id from public.v_ind_khld_so1_0
    union all select 'A1',    period_code, actual, denominator, municipality_id from public.v_ind_khld_a1
    union all select 'A2',    period_code, actual, denominator, municipality_id from public.v_ind_khld_a2
    union all select 'A3',    period_code, actual, denominator, municipality_id from public.v_ind_khld_a3
    union all select 'B1',    period_code, actual, denominator, municipality_id from public.v_ind_khld_b1
    union all select 'SO2-0', period_code, actual, denominator, municipality_id from public.v_ind_khld_so2_0
    union all select 'C1',    period_code, actual, denominator, municipality_id from public.v_ind_khld_c1
    union all select 'C2',    period_code, actual, denominator, municipality_id from public.v_ind_khld_c2
    union all select 'D1',    period_code, actual, denominator, municipality_id from public.v_ind_khld_d1
    union all select 'D2',    period_code, actual, denominator, municipality_id from public.v_ind_khld_d2
    union all select 'SO3-0', period_code, actual, denominator, municipality_id from public.v_ind_khld_so3_0
    union all select 'E1',    period_code, actual, denominator, municipality_id from public.v_ind_khld_e1
    union all select 'F1',    period_code, actual, denominator, municipality_id from public.v_ind_khld_f1
    union all select 'F2',    period_code, actual, denominator, municipality_id from public.v_ind_khld_f2
    union all select 'F3',    period_code, actual, denominator, municipality_id from public.v_ind_khld_f3
    union all select 'SO4-0', period_code, actual, denominator, municipality_id from public.v_ind_khld_so4_0
    union all select 'G1',    period_code, actual, denominator, municipality_id from public.v_ind_khld_g1
    union all select 'G2',    period_code, actual, denominator, municipality_id from public.v_ind_khld_g2
    union all select 'H1',    period_code, actual, denominator, municipality_id from public.v_ind_khld_h1
    union all select 'H2',    period_code, actual, denominator, municipality_id from public.v_ind_khld_h2
  ) x
 where (auth.uid() is null or public.is_staff() or public."current_role"() = 'partner_viewer')
   and (auth.uid() is null or public.can_see_municipality(municipality_id));

-- ── grants: the leaves and helpers to nobody; the three read views as before ──
do $grants$
declare v text;
begin
  for v in select c.relname from pg_class c join pg_namespace n on n.oid = c.relnamespace
            where n.nspname = 'public' and c.relkind = 'v'
              and (c.relname like 'v\_ind\_khld\_%' or c.relname in ('v_khld_milestone_established', 'v_khld_volunteer_occasion', 'v_khld_guidance_completed'))
  loop
    execute format('revoke all on public.%I from public, anon, authenticated', v);
  end loop;
end $grants$;
revoke all on public.v_khld_indicator_unique, public.v_khld_indicator_status, public.v_public_khld_whats_on from public, anon;
grant select on public.v_khld_indicator_unique, public.v_khld_indicator_status to authenticated;
grant select on public.v_public_khld_whats_on to anon, authenticated;

-- ── verification ─────────────────────────────────────────────────────────
do $verify$
declare
  v_n int;
begin
  -- Sahel Horan's and Ramtha's figures, every row, unchanged
  select count(*) into v_n from (
    (select * from _0163_actual_before
     except all
     select * from public.v_indicator_actual
      where municipality_id in ('00000000-0000-4000-8000-00000000005a', '00000000-0000-4000-8000-0000000000a1'))
    union all
    (select * from public.v_indicator_actual
      where municipality_id in ('00000000-0000-4000-8000-00000000005a', '00000000-0000-4000-8000-0000000000a1')
     except all
     select * from _0163_actual_before)) d;
  if v_n <> 0 then
    raise exception '0163: % Sahel Horan / Ramtha indicator rows changed', v_n;
  end if;
  -- 21 Khalidiyah indicators, one row per period each, no period doubled
  select count(*) into v_n from public.v_indicator_actual where municipality_id = '00000000-0000-4000-8000-0000000000b2';
  if v_n <> 21 * (select count(*) from public.reporting_period where municipality_id = '00000000-0000-4000-8000-0000000000b2') then
    raise exception '0163: % Khalidiyah rows in v_indicator_actual, expected 21 per period', v_n;
  end if;
  if exists (select 1 from public.v_indicator_actual where municipality_id = '00000000-0000-4000-8000-0000000000b2'
              group by code, period_code having count(*) > 1) then
    raise exception '0163: a Khalidiyah indicator has two rows for one period';
  end if;
  -- every indicator names its view, and the view exists
  if exists (select 1 from public.indicator i join public.municipality m on m.id = i.municipality_id and m.code = 'KHLD'
              where to_regclass('public.' || i.view_name) is null) then
    raise exception '0163: an indicator names a view that does not exist';
  end if;
  -- the leaves are revoked from authenticated (0114's lesson: a create view re-grants)
  if exists (select 1 from pg_class c join pg_namespace n on n.oid = c.relnamespace
              where n.nspname = 'public' and c.relname like 'v\_ind\_khld\_%'
                and has_table_privilege('authenticated', c.oid, 'select')) then
    raise exception '0163: a Khalidiyah leaf view is readable by authenticated';
  end if;
  -- the public view answers anon
  set local role anon;
  perform 1 from public.v_public_khld_whats_on;
  reset role;
end $verify$;
